<script lang="ts">
 import {onDestroy,untrack} from 'svelte';import {Session} from '$lib/stores';
 import {createChapterCreditsController} from './chapter-credits-client';import type {ChapterCredit} from './native-team-client';
 import UnsavedEditorGuard from './UnsavedEditorGuard.svelte';import {allowEditorDiscard} from './editor-unsaved';
 let {chapterId,version,disabled=false,onChanged=async()=>{},onState=()=>{}}:{chapterId:string;version:number;disabled?:boolean;onChanged?:()=>Promise<void>;onState?:(state:{busy:boolean;dirty:boolean;pending:boolean})=>void}=$props();
 let owner=$state.raw<Awaited<ReturnType<typeof createChapterCreditsController>>>(),rows=$state<ChapterCredit[]>([]),saved=$state('[]'),loadedVersion=$state(0),busy=$state(false),pending=$state(false),ready=$state(false),message=$state('');let disposed=false,epoch=0;
 const dirty=$derived(JSON.stringify(rows)!==saved);
 $effect(()=>onState({busy,dirty,pending}));
 onDestroy(()=>{disposed=true;epoch++;owner?.dispose();onState({busy:false,dirty:false,pending:false});});
 async function initialize(){const session=$Session,id=chapterId,token=++epoch;owner?.dispose();owner=undefined;rows=[];saved='[]';ready=false;pending=false;message='';busy=true;if(!session?.identity?.id){busy=false;return;}const check=()=>{if(disposed||token!==epoch||session!==$Session||chapterId!==id)throw Error('The chapter account changed.');};try{const next=await createChapterCreditsController(session.identity.id,id,check);check();owner=next;const value=await next.read();check();rows=value.credits;saved=JSON.stringify(rows);loadedVersion=value.version;pending=next.pending();ready=true;}catch(e){if(token===epoch)message=e instanceof Error?e.message:'Credits could not be loaded.';}finally{if(token===epoch)busy=false;}}
 $effect(()=>{const session=$Session,id=chapterId;untrack(()=>{void session;void id;void initialize();});});
 async function save(){if(!owner||!ready||busy||pending||disabled||loadedVersion!==version)return;const current=owner,token=epoch;busy=true;message='';try{const value=await current.save(version,rows);current.check();if(token!==epoch)return;rows=value.credits;saved=JSON.stringify(rows);loadedVersion=value.version;message='Public chapter credits saved.';await onChanged();}catch(e){if(token===epoch)message=e instanceof Error?e.message:'Credits could not be confirmed.';}finally{if(token===epoch){busy=false;pending=current.pending();}}}
 function reload(){if(!busy&&allowEditorDiscard(dirty,message=>window.confirm(message)))void initialize();}
</script>
<section class="space-y-3 rounded border p-4" aria-label="Chapter credits"><h2 class="font-medium">Chapter credits</h2><p>Public credits on this site. Credits do not grant membership or editing permissions.</p><details class="text-sm"><summary>Where credits appear</summary><p>These credits appear in this site’s reader. They are saved locally and are not added to the original signed publication or copied to other sites.</p></details>{#if message}<p role="status">{message}</p>{/if}{#if pending}<p role="alert">An earlier credits change is unconfirmed. Do not send it again. Refresh to inspect the saved credits or ask support to check the result.</p>{/if}{#if ready&&loadedVersion!==version}<p>This chapter changed. Refresh credits before saving.</p>{/if}<UnsavedEditorGuard {dirty} />
 <fieldset class="space-y-3" disabled={!ready||busy||pending||disabled||loadedVersion!==version}>{#each rows as credit,index}<div class="flex flex-wrap gap-2"><label>Contribution<select class="block rounded border p-2" bind:value={credit.role}><option value="translator">Translator</option><option value="editor">Editor</option><option value="typesetter">Typesetter</option></select></label><label class="flex-1">Display name<input class="block w-full rounded border p-2" bind:value={credit.name} maxlength="120" required /></label><button type="button" class="rounded border px-3" onclick={()=>rows=rows.filter((_,i)=>i!==index)}>Remove credit</button></div>{/each}<button type="button" class="rounded border px-3 py-2" disabled={rows.length>=30} onclick={()=>rows=[...rows,{role:'translator',name:''}]}>Add credit</button><button type="button" class="rounded border px-3 py-2" disabled={!dirty||rows.some(r=>!r.name.trim())} onclick={save}>Save credits</button></fieldset><button type="button" class="rounded border px-3 py-2" disabled={busy} onclick={reload}>Refresh credits</button>
</section>
